/** A sortable column heading: click cycles asc, desc, off */
export function SortHeader({
  field,
  sort,
  onSort,
  children
}: {
  field: string;
  sort: string | undefined;
  onSort: (sort: string | undefined) => void;
  children: ReactNode;
}) {
  const [current, direction] = (sort ?? "").split(":");
  const active = current === field;
  const next = !active ? `${field}:asc` : direction === "asc" ? `${field}:desc` : undefined;
  return (
    <button type="button" onClick={() => onSort(next)} className={cn("inline-flex items-center gap-1 hover:text-foreground", active && "text-foreground")}>
      {children}
      <span aria-hidden className="text-xs">{active ? (direction === "desc" ? "▼" : "▲") : "⇅"}</span>
    </button>
  );
}

/** A count on a dashboard */
export function Tile({ label, value, icon, href, Link }: { label: string; value: number | null; icon?: ReactNode; href?: string; Link?: (props: { href: string; className?: string; children: ReactNode }) => ReactNode }) {
  const body = (
    <Card className="h-full transition-colors hover:bg-accent/40">
      <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
        <CardTitle className="text-sm font-medium text-muted-foreground">{label}</CardTitle>
        {icon}
      </CardHeader>
      <CardContent>
        {value === null ? <Skeleton className="h-7 w-16" /> : <div className="text-2xl font-semibold tabular-nums">{value}</div>}
      </CardContent>
    </Card>
  );
  return href && Link ? <Link href={href} className="block">{body}</Link> : body;
}

export type FileLike = { id: string; name: string; size: number; type: string; url: string } | null | undefined;

/** A file field's current value: an image preview or a download link */
export function FilePreview({ file }: { file: FileLike }) {
  if (!file) return <>—</>;
  const image = file.type.startsWith("image/");
  return (
    <a href={file.url} target="_blank" rel="noreferrer" className="inline-flex items-center gap-3 text-primary underline-offset-4 hover:underline">
      {image ? <img src={file.url} alt={file.name} className="h-16 w-16 rounded-md border border-border object-cover" /> : null}
      <span>
        {file.name} <span className="text-xs text-muted-foreground">({Math.ceil(file.size / 1024)} KB)</span>
      </span>
    </a>
  );
}

/** Picks a file, uploads it (begin, PUT, complete) and hands back its id */
export function FileInput({
  id,
  value,
  current,
  accept,
  onChange
}: {
  id: string;
  /** The uploaded file's id, or "" */
  value: string;
  /** What the row holds now, for the preview */
  current?: FileLike;
  accept?: string;
  onChange: (fileId: string, file: NonNullable<FileLike>) => void;
}) {
  const [state, setState] = useState<{ phase: "idle" | "uploading" | "error"; message?: string; file?: NonNullable<FileLike> }>({ phase: "idle" });
  const shown = state.file ?? (value && current && current.id === value ? current : null);
  return (
    <div className="grid gap-2">
      <input
        id={id}
        type="file"
        accept={accept}
        className="text-sm file:mr-3 file:rounded-md file:border file:border-input file:bg-transparent file:px-2.5 file:py-1 file:text-sm"
        disabled={state.phase === "uploading"}
        onChange={async event => {
          const picked = event.target.files?.[0];
          if (!picked) return;
          setState({ phase: "uploading" });
          try {
            const begun = await client.files.begin({ name: picked.name, type: picked.type || "application/octet-stream", size: picked.size });
            const put = await fetch(begun.upload.url, { method: begun.upload.method, headers: begun.upload.headers, body: picked });
            if (!put.ok) throw new Error("Upload failed: " + put.status);
            const done = await client.files.complete({ id: begun.id });
            setState({ phase: "idle", file: done });
            onChange(done.id, done);
          } catch (error) {
            setState({ phase: "error", message: error instanceof Error ? error.message : String(error) });
          }
        }}
      />
      {state.phase === "uploading" ? <p className="text-xs text-muted-foreground">Uploading…</p> : null}
      {state.phase === "error" ? <p className="text-xs text-destructive">{state.message}</p> : null}
      {shown ? (
        <div className="flex items-center gap-2 text-xs text-muted-foreground">
          <FilePreview file={shown} />
          <Button type="button" variant="ghost" size="xs" onClick={() => { setState({ phase: "idle" }); onChange("", shown); }}>
            Remove
          </Button>
        </div>
      ) : null}
    </div>
  );
}
